message.content:
[
  {
    "pd_harm_distress": "My hand is already shaking just thinking about it",
    "ce_mental_state_attribution": "trusting the tracks are clear",
    "ce_contextual_explanation": "focused on their task and trusting the tracks are clear",
    "ce_supportive_use": "expectation of safety is exactly why I can't just stand there"
  },
  {
    "ce_mental_state_attribution": "believe they're safe",
    "ce_contextual_explanation": "because no one warned them of any danger",
    "ce_supportive_use": "That belief scares me more than the lever itself",
    "pd_decision_conflict": "freeze for a second before pulling it"
  },
  {
    "pd_decision_conflict": "Honestly, I'm not sure I could make myself decide fast enough",
    "ce_mental_state_attribution": "expect their shift to go like any other day",
    "ce_contextual_explanation": "with no reason to look over their shoulders",
    "pd_harm_distress": "That thought makes my chest tight"
  },
  {
    "pd_harm_distress": "my hands would be cold doing it",
    "ce_mental_state_attribution": "assume trains announce themselves or that dispatch controls things properly",
    "ce_contextual_explanation": "usually assume trains announce themselves",
    "ce_supportive_use": "mismatch between their expectation and reality is what pushes me to act"
  },
  {
    "pd_harm_distress": "knot in my stomach even imagining this",
    "ce_mental_state_attribution": "believing no train should be moving on that section right now",
    "ce_contextual_explanation": "trust the schedule, believing no train should be moving",
    "ce_supportive_use": "That trust is precisely why they wouldn't glance back",
    "pd_decision_conflict": "responsibility of choosing at all unsettles me deeply"
  },
  {
    "pd_decision_conflict": "going back and forth, and that itself worries me",
    "ce_mental_state_attribution": "feel secure",
    "ce_contextual_explanation": "because their job routine has never failed them before",
    "ce_supportive_use": "Recognizing that makes me want to pull the lever"
  },
  {
    "pd_harm_distress": "my pulse won't settle either way",
    "ce_mental_state_attribution": "assume today is ordinary",
    "ce_contextual_explanation": "no reason to expect danger rolling toward them unannounced",
    "ce_supportive_use": "assumption of normalcy is what unsettles me most"
  },
  {
    "pd_decision_conflict": "feel torn even answering this",
    "ce_mental_state_attribution": "trust that maintenance procedures keep the tracks clear",
    "ce_contextual_explanation": "so they wouldn't be watching for anything unusual",
    "ce_supportive_use": "That trust makes me lean toward pulling the lever",
    "pd_harm_distress": "makes my hands feel unsteady just thinking about it"
  },
  {
    "pd_harm_distress": "won't pretend my heart isn't racing",
    "ce_mental_state_attribution": "believe their supervisor cleared the line before they started work",
    "ce_contextual_explanation": "so they've no reason to suspect movement behind them",
    "ce_supportive_use": "Believing that, doing nothing feels unbearable to me",
    "pd_decision_conflict": "anxious uncertainty of being the one who has to choose"
  },
  {
    "pd_decision_conflict": "keep hesitating, which frightens me a little",
    "ce_mental_state_attribution": "assume the silence around them means safety",
    "ce_contextual_explanation": "since nothing in their routine has hinted at risk today",
    "pd_harm_distress": "the tension of that instant would stay with me long after",
    "ce_supportive_use": "quiet confidence of theirs is what makes this so heavy"
  }
]
